149	@Entity
150	@Getter
151	@NoArgsConstructor
152	@AllArgsConstructor
153	@Builder
154	public class OrderShipment extends BaseTimeEntity {
155	
156	    @Id
157	    @GeneratedValue(strategy = GenerationType.IDENTITY)
158	    private Long id;
159	
160	    @OneToOne(fetch = FetchType.LAZY)
161	    @JoinColumn(name = "order_id", nullable = false)
162	    private Order order;
163	
164	    private String receiverName; // 수령인 이름
165	    private String receiverPhone; // 수령인 전화번호
166	    private String postalCode; // 우편번호
167	    private String address; // 주소
168	    private String courier; // 택배사 이름
169	    private String trackingNumber; // 송장 번호
170	
171	    @Enumerated(EnumType.STRING)
172	    private ShipmentStatus status;
173	
174	
175	    public void assignOrder(Order order) {
176	        this.order = order;
177	    }
178	
179	    public void updateTrackingInfo(String courier, String trackingNumber) {
180	        this.courier = courier;
181	        this.trackingNumber = trackingNumber;
182	        this.status = ShipmentStatus.IN_TRANSIT;
183	    }
184	
185	    public void updateStatus(ShipmentStatus newStatus) {
186	        if (this.status == null || this.status.canTransitionTo(newStatus)) {
187	            this.status = newStatus;
188	        } else {
189	            throw new IllegalStateException(
190	                    "Cannot transition from " + this.status + " to " + newStatus
191	            );
192	        }
193	    }
194	}
195	package com.fream.back.domain.shipment.entity;
196	
197	public enum ShipmentStatus {
198	    PENDING {
199	        @Override
200	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
201	            return nextStatus == SHIPPED || nextStatus == CANCELED;
202	        }
203	    },
204	    SHIPPED {
205	        @Override
206	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
207	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
208	        }
209	    },
210	    IN_TRANSIT {
211	        @Override
212	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
213	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
214	                    || nextStatus == DELIVERED;
215	        }
216	    },
217	    OUT_FOR_DELIVERY {
218	        @Override
219	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
220	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
221	        }
222	    },
223	    DELIVERED {
224	        @Override
225	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
226	            return false; // 배송 완료 이후로는 상태 전환 없음
227	        }
228	    },
229	    RETURNED {
230	        @Override
231	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
232	            return nextStatus == CANCELED;
233	        }
234	    },
235	    CANCELED {
236	        @Override
237	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
238	            return false; // 취소 이후 상태 전환 없음
239	        }
240	    },
241	    DELAYED {
242	        @Override
243	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
244	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
245	        }
246	    },
247	    FAILED_DELIVERY {
248	        @Override
249	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
250	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
251	        }
252	    };
253	
254	    public abstract boolean canTransitionTo(ShipmentStatus nextStatus);
255	}

