196	
197	public enum ShipmentStatus {
198	    PENDING {
199	        @Override
200	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
201	            return nextStatus == SHIPPED || nextStatus == CANCELED;
202	        }
203	    },
204	    SHIPPED {
205	        @Override
206	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
207	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
208	        }
209	    },
210	    IN_TRANSIT {
211	        @Override
212	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
213	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
214	                    || nextStatus == DELIVERED;
215	        }
216	    },
217	    OUT_FOR_DELIVERY {
218	        @Override
219	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
220	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
221	        }
222	    },
223	    DELIVERED {
224	        @Override
225	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
226	            return false; // 배송 완료 이후로는 상태 전환 없음
227	        }
228	    },
229	    RETURNED {
230	        @Override
231	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
232	            return nextStatus == CANCELED;
233	        }
234	    },
235	    CANCELED {
236	        @Override
237	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
238	            return false; // 취소 이후 상태 전환 없음
239	        }
240	    },
241	    DELAYED {
242	        @Override
243	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
244	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
245	        }
246	    },
247	    FAILED_DELIVERY {
248	        @Override
249	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
250	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
251	        }
252	    };
253	
254	    public abstract boolean canTransitionTo(ShipmentStatus nextStatus);
255	}

