359	/**
360	 * 배송 상태 배치 처리를 위한 ItemProcessor
361	 * 주문 배송 상태를 조회하고 처리합니다.
362	 */
363	@Slf4j
364	public class ShipmentItemProcessor implements ItemProcessor<OrderShipment, OrderShipment> {
365	
366	    private final PlaywrightBrowserManager browserManager;
367	    private final NotificationCommandService notificationService;
368	    private final OrderShipmentCommandService orderService;
369	
370	    private static final String TRACKING_URL_PREFIX = "https://trace.cjlogistics.com/next/tracking.html?wblNo=";
371	    private static final String STATUS_SELECTOR = "tbody#statusDetail tr";
372	    private static final int TIMEOUT_MS = 30000; // 30초
373	
374	    /**
375	     * 배송 상태 처리기 생성자
376	     *
377	     * @param browserManager Playwright 브라우저 관리자
378	     * @param notificationService 알림 서비스
379	     * @param orderService 주문 서비스
380	     */
381	    public ShipmentItemProcessor(
382	            PlaywrightBrowserManager browserManager,
383	            NotificationCommandService notificationService,
384	            OrderShipmentCommandService orderService
385	    ) {
386	        this.browserManager = browserManager;
387	        this.notificationService = notificationService;
388	        this.orderService = orderService;
389	    }
390	
391	    /**
392	     * 주문 배송의 상태를 외부 서비스를 통해 조회하고 업데이트합니다.
393	     *
394	     * @param orderShipment 처리할 배송 정보
395	     * @return 업데이트된 배송 정보
396	     * @throws Exception 처리 중 오류 발생 시
397	     */
398	    @Override
399	    public OrderShipment process(OrderShipment orderShipment) throws Exception {
400	        String trackingNumber = orderShipment.getTrackingNumber();
401	        Long shipmentId = orderShipment.getId();
402	
403	        if (trackingNumber == null || trackingNumber.isBlank()) {
404	            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
405	            throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
406	        }
407	
408	        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
409	                shipmentId, trackingNumber, orderShipment.getStatus());
410	
411	        Page page = null;
412	        try {
413	            // browserManager를 통해 페이지 생성
414	            page = browserManager.newPage();
415	            if (page == null) {
416	                throw new ShipmentException(ShipmentErrorCode.BROWSER_INITIALIZATION_ERROR);
417	            }
418	
419	            // 타임아웃 설정
420	            page.setDefaultTimeout(TIMEOUT_MS);
421	
422	            // 배송 추적 URL로 이동
423	            String url = TRACKING_URL_PREFIX + trackingNumber;
424	            log.debug("배송 조회 페이지로 이동: {}", url);
425	            page.navigate(url);
426	
427	            // 배송 상태 테이블 로드 대기
428	            log.debug("배송 상태 테이블 로드 대기");
429	            page.waitForSelector(STATUS_SELECTOR);
430	
431	            // 최종 HTML 가져오기
432	            String renderedHtml = page.content();
433	            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());
434	
435	            // HTML 파싱하여 배송 상태 추출
436	            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
437	            ShipmentStatus newStatus = mapToShipmentStatus(statusText);
438	
439	            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
440	                    shipmentId, statusText, newStatus);
441	
442	            // 현재 상태와 동일한 경우 중복 처리 방지
443	            if (orderShipment.getStatus() == newStatus) {
444	                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
445	                        shipmentId, newStatus);
446	                return orderShipment;
447	            }
448	
449	            // 상태에 따른 처리
450	            if (newStatus == ShipmentStatus.DELIVERED) {
451	                log.info("배송 완료 처리: shipmentId={}, orderId={}",
452	                        shipmentId, orderShipment.getOrder().getId());
453	
454	                // 배송 상태 업데이트
455	                orderShipment.updateStatus(ShipmentStatus.DELIVERED);
456	
457	                // 주문 완료 처리 및 알림
458	                orderService.completeOrder(orderShipment.getOrder().getId());
459	                notificationService.notifyShipmentCompleted(orderShipment.getOrder());
460	
461	            } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
462	                log.info("배송 출발 처리: shipmentId={}", shipmentId);
463	                orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
464	
465	            } else {
466	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
467	                orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
468	            }
469	
470	            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
471	                    shipmentId, orderShipment.getStatus());
472	
473	            return orderShipment;
474	
475	        } catch (Exception e) {
476	            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
477	                    shipmentId, trackingNumber, e.getMessage(), e);
478	
479	            // ShipmentException 타입이 아닌 경우 래핑
480	            if (!(e instanceof ShipmentException)) {
481	                throw new ShipmentException(
482	                        ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
483	                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
484	                        e
485	                );
486	            }
487	            throw e;
488	        } finally {
489	            // 페이지 리소스 해제
490	            if (page != null) {
491	                try {
492	                    page.close();
493	                    log.debug("페이지 리소스 해제 완료");
494	                } catch (Exception e) {
495	                    log.warn("페이지 닫기 실패: {}", e.getMessage());
496	                }
497	            }
498	        }
499	    }
500	
501	    /**
502	     * HTML에서 배송 상태를 파싱합니다.
503	     *
504	     * @param html 파싱할 HTML 문자열
505	     * @param trackingNumber 로깅용 운송장 번호
506	     * @return 배송 상태 문자열
507	     * @throws ShipmentException 파싱 실패 시 발생
508	     */
509	    private String parseStatusFromHtml(String html, String trackingNumber) {
510	        try {
511	            Document doc = Jsoup.parse(html);
512	            Elements rows = doc.select(STATUS_SELECTOR);
513	
514	            if (rows.isEmpty()) {
515	                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
516	                throw new ShipmentException(
517	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
518	                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
519	                );
520	            }
521	
522	            // 마지막 행(최신 상태)의 5번째 컬럼 선택
523	            String statusText = rows.last().select("td").get(4).text().trim();
524	
525	            if (statusText.isEmpty()) {
526	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
527	                throw new ShipmentException(
528	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
529	                        "배송 상태 정보를 찾을 수 없습니다."
530	                );
531	            }
532	
533	            return statusText;
534	
535	        } catch (IndexOutOfBoundsException e) {
536	            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
537	            throw new ShipmentException(
538	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
539	                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
540	                    e
541	            );
542	        } catch (Exception e) {
543	            if (e instanceof ShipmentException) {
544	                throw (ShipmentException) e;
545	            }
546	
547	            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
548	            throw new ShipmentException(
549	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
550	                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
551	                    e
552	            );
553	        }
554	    }
555	
556	    /**
557	     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
558	     *
559	     * @param statusText 배송사 상태 텍스트
560	     * @return 매핑된 ShipmentStatus
561	     */
562	    private ShipmentStatus mapToShipmentStatus(String statusText) {
563	        return switch (statusText) {
564	            case "배송완료" -> ShipmentStatus.DELIVERED;
565	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
566	            default -> ShipmentStatus.IN_TRANSIT;
567	        };
568	    }
